#!/usr/bin/env bash
# Backlog C11: OS-specific code stays inside drust/src/platform/.
#
# 1. `cfg` on an OS (target_os, target_family, unix, windows) anywhere else
#    fails outright.
# 2. A Linux system path literal ("/etc/...", "/home/...", ...) in non-test
#    code elsewhere may not grow: each file may hold at most the count in
#    platform-guard-baseline.txt. Lower a count when you remove paths
#    (`--update` rewrites the file); never raise one to make CI pass.
#
# Usage: platform-guard.sh [--update]
set -euo pipefail

root="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
src="$root/drust/src"
baseline="$root/.github/scripts/platform-guard-baseline.txt"

cd "$src"

cfg_hits="$(grep -rnE 'cfg!?\((not\()?(any\(|all\()?(target_os|target_family|unix|windows)' --include='*.rs' . \
    | sed 's|^\./||' | grep -v '^platform/' || true)"

# Code before the first `#[cfg(test)]` line, comments dropped, Linux paths counted.
count_paths() {
    awk '
        /^[[:space:]]*#\[cfg\(test\)\]/ { exit }
        /^[[:space:]]*\/\// { next }
        {
            line = $0
            while (match(line, /"\/(etc|home|var|usr|opt|run|proc|sys|srv|root|bin|sbin|lib|dev|tmp)(\/|")/)) {
                n++
                line = substr(line, RSTART + RLENGTH)
            }
        }
        END { print n + 0 }
    ' "$1"
}

current="$(find . -name '*.rs' -not -path './platform/*' | sed 's|^\./||' | sort | while read -r file; do
    n="$(count_paths "$file")"
    if [ "$n" -gt 0 ]; then
        printf '%s %s\n' "$n" "$file"
    fi
done)"

if [ "${1:-}" = "--update" ]; then
    {
        echo "# Linux path literals allowed per file outside drust/src/platform/ (backlog C11)."
        echo "# Generated by platform-guard.sh --update. Counts may only go down."
        printf '%s\n' "$current"
    } > "$baseline"
    echo "Baseline written: $(printf '%s\n' "$current" | grep -c . || true) files."
    exit 0
fi

failed=0

if [ -n "$cfg_hits" ]; then
    echo "OS cfg outside drust/src/platform/ (move it behind a platform interface):"
    printf '  %s\n' "$cfg_hits"
    failed=1
fi

declare -A allowed=()
while read -r n file; do
    case "$n" in '' | '#'*) continue ;; esac
    allowed["$file"]="$n"
done < "$baseline"

while read -r n file; do
    [ -n "$file" ] || continue
    limit="${allowed[$file]:-0}"
    if [ "$n" -gt "$limit" ]; then
        echo "drust/src/$file: $n Linux path literal(s), baseline allows $limit. Use platform::Paths."
        failed=1
    fi
done <<< "$current"

if [ "$failed" -ne 0 ]; then
    exit 1
fi
echo "Platform guard passed."
